// 阶段1课程数据（第1-13周），由 H5 版自动提取
module.exports = [{"w":1,"p":1,"theme":"问候与自我介绍","d":[{"t":"打招呼与告别","obj":"学会最基本的问候用语，掌握be动词（am/is/are）","time":"40分钟","v":[{"w":"hello","m":"你好","p":"int.","e":"Hello! Nice to meet you."},{"w":"goodbye","m":"再见","p":"int.","e":"Goodbye! See you tomorrow."},{"w":"please","m":"请","p":"adv.","e":"Please sit down."},{"w":"sorry","m":"对不起的；遗憾的","p":"adj.","e":"I am sorry, I am late."},{"w":"welcome","m":"欢迎","p":"int./v.","e":"Welcome to my home."}],"g":{"t":"be动词（am / is / are）","exp":"be动词相当于中文的“是”，是所有英语句子的地基。口诀：I用am，you/we/they用are，he/she/it用is。先把它背到脱口而出。","ex":["I am a student.","You are my friend.","She is from China."]},"pr":"1) 抄写5个问候语并大声朗读各10遍。2) 用be动词写3句话介绍自己。3) 用今天的5个新词各造1句话。","tip":"零基础最大的敌人是不敢开口。从今天起，每天必须大声朗读至少15分钟，读错也无所谓，嘴巴先动起来。"},{"t":"介绍自己的名字","obj":"学会说出并询问名字，掌握be动词的否定句和疑问句","time":"40分钟","v":[{"w":"name","m":"名字","p":"n.","e":"My name is Li Ming."},{"w":"introduce","m":"介绍","p":"v.","e":"Let me introduce myself."},{"w":"meet","m":"遇见；见面","p":"v.","e":"Nice to meet you."},{"w":"friend","m":"朋友","p":"n.","e":"She is my best friend."},{"w":"call","m":"称呼；打电话","p":"v.","e":"You can call me Xiao Li."}],"g":{"t":"be动词的否定句与疑问句","exp":"否定句在be后加not：I am not / is not (isn't) / are not (aren't)。疑问句把be提到主语前：Are you...? Is he...? 回答用Yes, I am. / No, I'm not.","ex":["I am not a teacher.","Are you a student?","Is she your friend?"]},"pr":"1) 写3句否定句和3句疑问句（用be动词）。2) 自问自答5组疑问句。3) 把昨天的自我介绍扩展到5句话。","tip":"疑问句语调要上扬，多听多模仿。以后每学一个新句型，先肯定、再否定、再疑问各练一遍。"},{"t":"我的家庭","obj":"学会介绍家庭成员，掌握人称代词主格","time":"40分钟","v":[{"w":"family","m":"家庭；家人","p":"n.","e":"There are four people in my family."},{"w":"father","m":"父亲","p":"n.","e":"My father is a driver."},{"w":"mother","m":"母亲","p":"n.","e":"My mother cooks very well."},{"w":"sister","m":"姐妹","p":"n.","e":"My sister is two years older than me."},{"w":"brother","m":"兄弟","p":"n.","e":"My brother likes playing football."}],"g":{"t":"人称代词主格（I / you / he / she / it / we / they）","exp":"主格放在动词前当主语。中文“我妈妈”里的“我”是形容词，英语只能说my mother。先记住：I=我，you=你/你们，he=他，she=她，it=它，we=我们，they=他们。","ex":["I love my family.","He is my father.","They are my parents."]},"pr":"1) 画出家庭树，用英文标出每位成员。2) 用人称代词+be动词写5句介绍家人的话。3) 朗读并背诵这5句话。","tip":"family在英美用法里常指“家人”，所以my family are all well（我的家人都好）也正确，考试中当“家庭”讲可用单数。"},{"t":"我的身份","obj":"学会说职业，掌握物主代词","time":"40分钟","v":[{"w":"student","m":"学生","p":"n.","e":"I am a student."},{"w":"teacher","m":"老师","p":"n.","e":"My teacher is very kind."},{"w":"doctor","m":"医生","p":"n.","e":"The doctor works in a hospital."},{"w":"worker","m":"工人","p":"n.","e":"My father is a factory worker."},{"w":"job","m":"工作（职业）","p":"n.","e":"She has a good job."}],"g":{"t":"物主代词（my / your / his / her / its / our / their）","exp":"物主代词相当于中文的“我的、你的、他的”。放在名词前：my book, your name, his father。注意its（它的）和it's（it is的缩写）写法不同。","ex":["My mother is a teacher.","Her job is interesting.","Their son is a doctor."]},"pr":"1) 用“物主代词+家庭成员+职业”写5句话。2) 大声朗读，把每句改成否定句。3) 口头回答：What's your father's job?","tip":"介绍职业记得加冠词：He is a doctor. 不说 He is doctor. 这是零基础最常犯的错误之一。"},{"t":"国家与语言","obj":"学会说国家、城市和语言，掌握be动词缩写形式","time":"40分钟","v":[{"w":"country","m":"国家","p":"n.","e":"China is a beautiful country."},{"w":"city","m":"城市","p":"n.","e":"Beijing is a big city."},{"w":"language","m":"语言","p":"n.","e":"English is a global language."},{"w":"English","m":"英语；英国的","p":"n./adj.","e":"I study English every day."},{"w":"speak","m":"说（某种语言）","p":"v.","e":"Do you speak English?"}],"g":{"t":"be动词缩写形式","exp":"口语中be动词几乎都用缩写：I'm, you're, he's, she's, it's, we're, they're。听力里出现的全是缩写读音，必须练到一听就懂。","ex":["I'm from China.","She's my English teacher.","We're good friends."]},"pr":"1) 写4句话：你的国家、城市、你会说的语言、你想学的语言。2) 全部改写成缩写形式再读5遍。3) 录音说一段20秒自我介绍。","tip":"回听自己的录音是进步最快的方法。第一次听会尴尬，坚持一周就能明显感觉不一样。"}],"sun":{"t":"第1周自检：问候与自我介绍","obj":"检验本周25个词汇和be动词的掌握情况","pr":"1) 听写测试：盖住英文，看中文默写本周25个词。2) 用be动词写10句话：介绍自己、家人、职业各若干。3) 录一段30秒英文自我介绍并回听，找出发音问题。","tip":"每周日的自检是记忆的“保存按钮”。错词抄3遍，下周继续滚动复习。"}},{"w":2,"p":1,"theme":"数字与时间","d":[{"t":"数字世界","obj":"掌握0-100的基数词，为听力数字题打基础","time":"40分钟","v":[{"w":"number","m":"数字","p":"n.","e":"Can you say the numbers in English?"},{"w":"count","m":"数；计算","p":"v.","e":"Please count from one to ten."},{"w":"zero","m":"零","p":"n.","e":"My phone number has two zeros."},{"w":"hundred","m":"百","p":"n./num.","e":"There are one hundred students."},{"w":"thousand","m":"千","p":"n./num.","e":"The town has three thousand people."}],"g":{"t":"基数词的构成规律","exp":"13-19结尾加-teen，注意thirteen和thirty的区别。20-90整十数结尾-ty。21=twenty-one，101=one hundred and one。英语没有“万”，一万=ten thousand。","ex":["I am twenty years old.","There are thirty days in April.","The book costs forty-five yuan."]},"pr":"1) 抄写0-20、30-100整十数各3遍。2) 用英语说出身边10样东西的数量。3) 写出自己的手机号、门牌号，用英语读出来。","tip":"数字是雅思听力第一关。以后看到任何数字（价格、日期、号码）都习惯性用英语读出来。"},{"t":"星期与月份","obj":"掌握星期、月份和序数词，学会表达日期","time":"40分钟","v":[{"w":"week","m":"星期；周","p":"n.","e":"There are seven days in a week."},{"w":"month","m":"月份","p":"n.","e":"January is the first month."},{"w":"Monday","m":"星期一","p":"n.","e":"I have English class on Monday."},{"w":"January","m":"一月","p":"n.","e":"My birthday is in January."},{"w":"weekend","m":"周末","p":"n.","e":"I usually rest at the weekend."}],"g":{"t":"序数词与日期表达","exp":"first, second, third是不规则，其余加-th（注意fifth, eighth, ninth, twelfth拼写）。日期写法：May 1st读作May the first。星期和月份首字母必须大写。","ex":["Today is October the third.","Sunday is the first day of a week.","February is the second month."]},"pr":"1) 默写一周7天和12个月。2) 写出今天的日期、自己的生日。3) 用on+星期、in+月份各造3句。","tip":"介词口诀：时间点用at，日期和星期用on，月份年份用in。听力日期题最爱考13th和30th的区分。"},{"t":"现在几点","obj":"掌握时间的表达方法","time":"40分钟","v":[{"w":"time","m":"时间；次","p":"n.","e":"What time is it now?"},{"w":"clock","m":"时钟","p":"n.","e":"The clock on the wall is slow."},{"w":"hour","m":"小时","p":"n.","e":"The class lasts two hours."},{"w":"minute","m":"分钟","p":"n.","e":"Wait for me for five minutes."},{"w":"half","m":"一半；半","p":"n./adj.","e":"I will be back in half an hour."}],"g":{"t":"时间表达法","exp":"整点用o'clock：7:00 seven o'clock。半点用half past：7:30 half past seven。一刻用quarter past/to：7:15 quarter past seven，7:45 quarter to eight。也可以直接说seven thirty。","ex":["It is nine o'clock.","The meeting starts at half past two.","I get up at a quarter to seven."]},"pr":"1) 写出6个时间点（含半点和刻钟）并用英语读出。2) 写出自己的起床、午饭、睡觉时间。3) 画一个钟表，随机拨10次指针报时。","tip":"听力里past和to一响就要马上反应方向：past=过几分（分在前），to=差几分（分在后）。"},{"t":"我的作息","obj":"学会描述日常作息，掌握频度副词","time":"40分钟","v":[{"w":"morning","m":"早晨","p":"n.","e":"I do exercise in the morning."},{"w":"afternoon","m":"下午","p":"n.","e":"We have a meeting this afternoon."},{"w":"evening","m":"晚上","p":"n.","e":"I watch TV in the evening."},{"w":"daily","m":"每日的","p":"adj.","e":"Reading is my daily habit."},{"w":"usually","m":"通常","p":"adv.","e":"I usually go to bed at eleven."}],"g":{"t":"频度副词（always / usually / often / sometimes / never）","exp":"频度副词放在实义动词前、be动词后。从100%到0%排序：always(总是) > usually(通常) > often(经常) > sometimes(有时) > never(从不)。","ex":["I always have breakfast at seven.","She is usually late.","We never watch TV at noon."]},"pr":"1) 写6句自己的日常作息，每句用不同的频度副词。2) 把6句话读熟并录音。3) 回答：How often do you do sports?","tip":"频度副词+一般现在时是描述习惯的黄金组合，口语Part 1几乎每天都会用到。"},{"t":"年龄与年份","obj":"学会谈论年龄和年份，掌握疑问句型","time":"40分钟","v":[{"w":"year","m":"年；年份","p":"n.","e":"This year is very important for me."},{"w":"age","m":"年龄","p":"n.","e":"She is my age."},{"w":"born","m":"出生的（bear的过去分词）","p":"adj.","e":"I was born in 1998."},{"w":"birthday","m":"生日","p":"n.","e":"Happy birthday to you!"},{"w":"old","m":"……岁的；老的","p":"adj.","e":"How old is your brother?"}],"g":{"t":"How old / When 疑问句","exp":"问年龄：How old are you? 回答直接说数字+years old。问时间点用When：When were you born? 注意born要用被动：I was born in...","ex":["How old are you? I am twenty-five.","When is your birthday?","She was born in 2000."]},"pr":"1) 写自己和家人的出生年份与年龄（5句）。2) 自问自答：How old...? / When...? 各5组。3) 用英语从2000数到2030。","tip":"年份读法：2000读two thousand，2008读two thousand and eight。听写年份时注意and经常被吞掉。"}],"sun":{"t":"第2周自检：数字与时间","obj":"检验数字、日期、时间的掌握情况","pr":"1) 随机听写20个数字（手机号、价格）。2) 默写7天+12个月+序数词1-12。3) 口头描述自己昨天一整天的作息时间。4) 复习第1周错词。","tip":"数字反应速度决定了雅思听力Section 1的成败，本周内容要反复练到条件反射。"}},{"w":3,"p":1,"theme":"家庭与人物描述","d":[{"t":"家庭关系","obj":"学会更多家庭称谓，掌握have got句型","time":"40分钟","v":[{"w":"relative","m":"亲戚","p":"n.","e":"I visited my relatives during the holiday."},{"w":"grandparent","m":"祖父母","p":"n.","e":"My grandparents live in the countryside."},{"w":"uncle","m":"叔叔；舅舅","p":"n.","e":"My uncle works in Shanghai."},{"w":"aunt","m":"阿姨；姑姑","p":"n.","e":"My aunt is a nurse."},{"w":"cousin","m":"表（堂）兄弟姐妹","p":"n.","e":"My cousin and I are the same age."}],"g":{"t":"have got 句型","exp":"英式口语中have got = have，表示“有”。I've got two cousins = I have two cousins。疑问句：Have you got...? 美式更常用Do you have...? 两种都要认识。","ex":["I have got two uncles.","She has got three cousins.","Have you got any brothers or sisters?"]},"pr":"1) 画一棵更大的家庭树，标注所有亲戚。2) 用have got写5句话描述家庭成员。3) 把5句话改成疑问句并自答。","tip":"口语考官问Do you have a large family? 你可以答Yes, I've got a big family with...显得更地道。"},{"t":"性格描述","obj":"学会描述性格的形容词，掌握形容词作表语","time":"40分钟","v":[{"w":"kind","m":"和蔼的；好心的","p":"adj.","e":"My grandma is very kind."},{"w":"friendly","m":"友好的","p":"adj.","e":"The neighbors are friendly to us."},{"w":"funny","m":"有趣的；滑稽的","p":"adj.","e":"My uncle is a funny man."},{"w":"quiet","m":"安静的","p":"adj.","e":"My brother is quiet but smart."},{"w":"smart","m":"聪明的","p":"adj.","e":"She is smart and hard-working."}],"g":{"t":"be + 形容词（表语结构）","exp":"英语说“某人怎样”用be+形容词：He is kind. 千万不能说He is a kind（漏名词）。形容词前可以加very, so, quite等程度词。","ex":["My mother is kind and patient.","The teacher is not strict.","Is your sister friendly?"]},"pr":"1) 用be+形容词写5句话描述家人的性格。2) 每句加一个程度词（very/so/quite）。3) 口头描述：你最好的朋友是什么性格？","tip":"描述性格是口语Part 1高频题。准备5个形容词+事例，随口就能说。"},{"t":"外貌描述","obj":"学会描述外貌，掌握wear的用法","time":"40分钟","v":[{"w":"tall","m":"高的","p":"adj.","e":"My father is tall and strong."},{"w":"short","m":"矮的；短的","p":"adj.","e":"She is short but very fast."},{"w":"hair","m":"头发","p":"n.","e":"My mother has long black hair."},{"w":"glasses","m":"眼镜","p":"n.","e":"My grandpa wears glasses."},{"w":"wear","m":"穿；戴","p":"v.","e":"He wears a blue jacket today."}],"g":{"t":"have / has + 特征 & wear + 物品","exp":"说“有”某种外貌特征用have/has：She has short hair。穿戴物品用wear（不用have）：He wears glasses。第三人称单数别忘了-s。","ex":["She has big eyes.","He wears a hat in summer.","My sister has curly hair."]},"pr":"1) 写5句话描述3位家人的外貌（身高、头发、眼镜等）。2) 朗读并背下来。3) 画一位家人，用英语标注外貌特征。","tip":"外貌描述顺序：先整体（tall/short）再细节（hair, eyes）。口语Part 2描述人物题可以直接套用。"},{"t":"家人的爱好","obj":"学会说爱好，掌握like/enjoy + doing","time":"40分钟","v":[{"w":"enjoy","m":"享受；喜爱","p":"v.","e":"My mother enjoys cooking."},{"w":"hobby","m":"爱好","p":"n.","e":"My hobby is reading novels."},{"w":"together","m":"一起","p":"adv.","e":"We have dinner together every day."},{"w":"love","m":"爱；很喜欢","p":"v.","e":"I love spending time with my family."},{"w":"spend","m":"度过；花费（时间）","p":"v.","e":"We spend weekends together."}],"g":{"t":"like / enjoy / love + 动词ing","exp":"表达“喜欢做某事”，like/enjoy/love后面接动词-ing形式：I enjoy reading。也可以说like to read，但enjoy只能接ing。这是中国考生高频错误。","ex":["My father enjoys fishing.","I like watching movies.","She loves singing and dancing."]},"pr":"1) 写5句话描述家人的爱好（用enjoy/like/love doing）。2) 改成疑问句自问自答。3) 口头介绍：We usually spend...together.","tip":"口语问What do you like doing? 答I enjoy...比I like...更出彩。同时记住enjoy后面不加to。"},{"t":"婚姻与家庭结构","obj":"学会更多家庭词汇，掌握名词所有格","time":"40分钟","v":[{"w":"marry","m":"结婚","p":"v.","e":"My parents married twenty years ago."},{"w":"husband","m":"丈夫","p":"n.","e":"Her husband is a policeman."},{"w":"wife","m":"妻子","p":"n.","e":"His wife teaches math."},{"w":"son","m":"儿子","p":"n.","e":"Their son studies in Canada."},{"w":"daughter","m":"女儿","p":"n.","e":"My daughter is five years old."}],"g":{"t":"名词所有格（'s）","exp":"表示“某人的”：my father's car（我爸爸的车）。以s结尾的复数只加'：my parents' house。注意of结构也可以：the house of my uncle，但口语更爱用's。","ex":["This is my mother's phone.","Tom's wife is a teacher.","My parents' room is big."]},"pr":"1) 用名词所有格写5句话（家庭成员+物品）。2) 描述一张全家福：谁是谁的谁。3) 朗读并录音。","tip":"描述人物关系时所有格特别好用：my sister's husband（我姐夫），比中文翻译腔自然得多。"}],"sun":{"t":"第3周自检：家庭话题","obj":"检验家庭词汇和描述句型的掌握情况","pr":"1) 听写本周25词。2) 写一段60词左右的家庭介绍：成员、性格、外貌、爱好。3) 录音60秒“介绍我的家庭”并回听。4) 复习第1-2周错词。","tip":"家庭话题是雅思口语Part 1的必考题，今天写的这段介绍可以直接背下来以后用。"}},{"w":4,"p":1,"theme":"日常起居","d":[{"t":"起床与睡觉","obj":"学会描述作息，掌握一般现在时","time":"40分钟","v":[{"w":"wake","m":"醒来","p":"v.","e":"I wake up at six every morning."},{"w":"get up","m":"起床","p":"phr.v.","e":"I get up quickly after waking up."},{"w":"sleep","m":"睡觉","p":"v./n.","e":"I usually sleep eight hours."},{"w":"breakfast","m":"早餐","p":"n.","e":"I have breakfast at half past six."},{"w":"dinner","m":"晚餐；正餐","p":"n.","e":"We have dinner at seven in the evening."}],"g":{"t":"一般现在时（I do / she does）","exp":"描述每天的习惯动作用一般现在时。主语是第三人称单数（he/she/it/单个人名）时动词加-s：she works。这是最重要的时态，先练到不假思索。","ex":["I get up at seven.","My mother cooks breakfast every day.","He goes to work by bus."]},"pr":"1) 写6句自己的日常作息（用一般现在时）。2) 把每句改成第三人称（My father...）。3) 朗读并背诵这6句话。","tip":"三单加-s看似简单，实际是雅思考生失分最多的点之一。每次写完he/she句子都回头检查一下。"},{"t":"洗漱与穿着","obj":"学会描述洗漱穿着，掌握现在进行时","time":"40分钟","v":[{"w":"wash","m":"洗","p":"v.","e":"I wash my face with cold water."},{"w":"brush","m":"刷","p":"v.","e":"Brush your teeth twice a day."},{"w":"dress","m":"穿衣；连衣裙","p":"v./n.","e":"She dresses her little son."},{"w":"clothes","m":"衣服","p":"n.","e":"I put on my sports clothes."},{"w":"shoe","m":"鞋","p":"n.","e":"These shoes are very comfortable."}],"g":{"t":"现在进行时（be + doing）","exp":"描述此刻正在发生的动作用现在进行时：I am studying English（我正在学英语）。结构=am/is/are+动词ing。动词ing变化：work→working, make→making, run→running。","ex":["I am washing my face.","She is brushing her teeth.","They are putting on their coats."]},"pr":"1) 写5句“此刻正在做的事”。2) 对着家人描述他们正在做什么（5句）。3) 快问快答：What are you doing now?","tip":"进行时是口语考官问What are you doing时的直接考点。描述照片、描述当下，都用它。"},{"t":"两种时态对比","obj":"分清“习惯”和“此刻”，掌握两种时态的区别","time":"40分钟","v":[{"w":"live","m":"居住；生活","p":"v.","e":"I live with my parents."},{"w":"stay","m":"停留；待","p":"v.","e":"I am staying at home today."},{"w":"now","m":"现在","p":"adv.","e":"I am doing my homework now."},{"w":"often","m":"经常","p":"adv.","e":"I often play basketball after school."},{"w":"at the moment","m":"此刻","p":"phr.","e":"He is writing a report at the moment."}],"g":{"t":"一般现在时 vs 现在进行时","exp":"一般现在时=习惯、常态：I read every night. 现在进行时=此刻、阶段：I am reading now. 信号词：usually/often/every day配一般现在时；now/look!/listen!/at the moment配进行时。","ex":["I usually work at home, but today I am working at the office.","She drinks tea every morning.","Look! It is raining."]},"pr":"1) 翻译5个句子（每句判断用哪种时态）。2) 写3组对比句：平时做什么 vs 现在在做什么。3) 朗读并录音。","tip":"考试里最爱你平时做X但今天正在做Y这种对比句。能自己造出对比句，说明两个时态都通了。"},{"t":"家务劳动","obj":"学会说家务，掌握一般现在时的疑问句","time":"40分钟","v":[{"w":"clean","m":"打扫；干净的","p":"v./adj.","e":"I clean my room on weekends."},{"w":"cook","m":"做饭","p":"v./n.","e":"My father cooks dinner on Sundays."},{"w":"sweep","m":"扫","p":"v.","e":"She sweeps the floor every day."},{"w":"wash up","m":"洗餐具","p":"phr.v.","e":"I wash up after dinner."},{"w":"tidy","m":"整理；整洁的","p":"v./adj.","e":"Let's tidy the room together."}],"g":{"t":"Do you...? / Does he...? 疑问句","exp":"借助动词do/does提问，后面动词用原形：Do you clean the room? Does she cook? 否定句同理：I don't cook. He doesn't cook. 三单的-s只出现在肯定句。","ex":["Do you often do housework?","Does your brother help at home?","I don't like washing dishes."]},"pr":"1) 写5个家务相关的疑问句并自答。2) 写5句否定句（说谁不做家务）。3) 采访家人：What housework do you do?","tip":"助动词do/does一出现，动词就打回原形。口诀：有does，动词不加s。"},{"t":"习惯与频率","obj":"学会问答频率，掌握How often句型","time":"40分钟","v":[{"w":"always","m":"总是","p":"adv.","e":"My mother always gets up early."},{"w":"sometimes","m":"有时","p":"adv.","e":"I sometimes forget my keys."},{"w":"never","m":"从不","p":"adv.","e":"He never drinks coffee."},{"w":"twice","m":"两次","p":"adv.","e":"I go swimming twice a week."},{"w":"habit","m":"习惯","p":"n.","e":"Reading before bed is a good habit."}],"g":{"t":"How often...? 频率问答","exp":"问频率用How often + 一般现在时：How often do you cook? 回答：every day / twice a week / three times a month / never。注意“次数+a+时间单位”。","ex":["How often do you do sports? Twice a week.","How often does she cook? Every day.","I never stay up late."]},"pr":"1) 用How often写5个问句问家人并记录答案。2) 写自己5个习惯的频率（every day/twice a week...）。3) 录音回答：How often do you study English?","tip":"once=一次，twice=两次，三次以上用three times。这个短语听力Section 1经常考，注意单复数。"}],"sun":{"t":"第4周自检：日常起居","obj":"检验一般现在时、现在进行时和频率表达","pr":"1) 听写本周25词。2) 写一篇80词短文《My Daily Routine》（用一般现在时+频度副词）。3) 时态小测：翻译10句（判断用哪种时态）。4) 复习第1-3周错词。","tip":"两种时态的对比选择是初中级英语的分水岭，测试正确率低于70%就把对比句再抄一遍。"}},{"w":5,"p":1,"theme":"饮食与点餐","d":[{"t":"食物基础","obj":"学会常见食物，掌握可数与不可数名词","time":"40分钟","v":[{"w":"rice","m":"米饭；大米","p":"n.","e":"We eat rice every day."},{"w":"bread","m":"面包","p":"n.","e":"I have bread and milk for breakfast."},{"w":"vegetable","m":"蔬菜","p":"n.","e":"Eat more vegetables, they are healthy."},{"w":"fruit","m":"水果","p":"n.","e":"Apples are my favorite fruit."},{"w":"meat","m":"肉","p":"n.","e":"My father likes eating meat."}],"g":{"t":"可数与不可数名词","exp":"rice/bread/water/meat是不可数名词，没有复数，不能加a，要说a bowl of rice、a piece of bread。vegetable/fruit/apple是可数名词，可以加s。哪些不可数没有规律，遇到一个记一个。","ex":["I eat a lot of rice.","She buys three apples.","Would you like a piece of bread?"]},"pr":"1) 把本周食物分成可数/不可数两栏。2) 用“a piece of / a bowl of / a glass of”各造2句。3) 写自己昨天的三餐都吃了什么。","tip":"雅思听力点餐场景里，可数不可数直接决定填空题的单复数，从一开始就要分清。"},{"t":"饮品与数量","obj":"学会点饮品，掌握some和any","time":"40分钟","v":[{"w":"water","m":"水","p":"n.","e":"Drink more water every day."},{"w":"tea","m":"茶","p":"n.","e":"My grandpa drinks green tea."},{"w":"coffee","m":"咖啡","p":"n.","e":"A cup of coffee, please."},{"w":"milk","m":"牛奶","p":"n.","e":"Children need milk every day."},{"w":"juice","m":"果汁","p":"n.","e":"Orange juice is my favorite drink."}],"g":{"t":"some 与 any","exp":"some用在肯定句：I want some water。any用在否定和疑问：I don't want any tea. Do you have any juice? 主动提供时疑问句也可用some：Would you like some coffee?","ex":["There is some milk in the fridge.","I don't have any coffee.","Do you want some tea?"]},"pr":"1) 用some/any各造3句（含否定和疑问）。2) 写一段点饮品对话（6句以上）。3) 列出自己家冰箱里的饮品清单。","tip":"点餐时说A coffee, please其实是省略了cup of。考试写作要写完整：a cup of coffee。"},{"t":"三餐与饥饿","obj":"学会谈论三餐，掌握how much/how many","time":"40分钟","v":[{"w":"meal","m":"一餐；饭","p":"n.","e":"Breakfast is the most important meal."},{"w":"lunch","m":"午餐","p":"n.","e":"I have lunch at school."},{"w":"snack","m":"零食","p":"n.","e":"Don't eat too many snacks."},{"w":"hungry","m":"饥饿的","p":"adj.","e":"I am very hungry now."},{"w":"full","m":"饱的；满的","p":"adj.","e":"I can't eat any more, I am full."}],"g":{"t":"How much / How many","exp":"问数量：可数名词用how many（How many eggs?），不可数用how much（How much milk?）。how much还可以问价格：How much is it? 一词两用要记住。","ex":["How many eggs do we have?","How much sugar do you want?","How much is this bag?"]},"pr":"1) 写6个问句（3个how many+3个how much）问家人。2) 写自己三餐的时间和食物。3) 口头描述：自己最饿的一次经历。","tip":"听力里问价格永远是How much is it? 而问数量要快速判断可不可数，决定单复数。"},{"t":"味道与喜好","obj":"学会描述味道，掌握表达喜好","time":"40分钟","v":[{"w":"sweet","m":"甜的","p":"adj.","e":"This cake is too sweet."},{"w":"salty","m":"咸的","p":"adj.","e":"The soup is a little salty."},{"w":"delicious","m":"美味的","p":"adj.","e":"Your dumplings are delicious!"},{"w":"taste","m":"尝起来；味道","p":"v./n.","e":"The milk tastes strange."},{"w":"favorite","m":"最喜爱的","p":"adj.","e":"Noodles are my favorite food."}],"g":{"t":"like + 名词 / like doing","exp":"表达喜好两个层次：I like apples（喜欢某物）；I like cooking（喜欢做某事，动词用ing）。程度的升级：I love... > I like... > I don't mind... > I hate...","ex":["I like sweet food.","She likes cooking for her family.","I don't mind washing up."]},"pr":"1) 写5句自己对不同食物的喜好（like/love/hate各用上）。2) 描述家里谁做的哪道菜最好吃。3) 回答：What's your favorite food? Why?","tip":"口语被问喜好时，一定加一句原因（Because...），只答一句会被认为交流意愿不足。"},{"t":"餐厅点餐","obj":"掌握餐厅场景对话，学会礼貌请求","time":"40分钟","v":[{"w":"order","m":"点餐；命令","p":"v./n.","e":"Are you ready to order?"},{"w":"menu","m":"菜单","p":"n.","e":"Can I see the menu, please?"},{"w":"bill","m":"账单","p":"n.","e":"Could we have the bill, please?"},{"w":"waiter","m":"服务员（男）","p":"n.","e":"The waiter is very polite."},{"w":"restaurant","m":"餐厅","p":"n.","e":"We found a nice restaurant."}],"g":{"t":"情态动词 can / could（礼貌请求）","exp":"点餐万能句型：Can I have..., please? / Could I have...?（更礼貌）。Could you...?是请对方做事。情态动词后接动词原形，没有人称变化。","ex":["Can I have a glass of water, please?","Could you bring me the menu?","I'd like a beef noodle, please."]},"pr":"1) 写一段完整的点餐对话（顾客+服务员共10句）。2) 大声分角色朗读。3) 记住三个万能句：Can I have...? / Could I...? / I'd like...","tip":"I'd like = I would like，比I want礼貌得多。在国外点餐说I want会被认为粗鲁。"}],"sun":{"t":"第5周自检：饮食话题","obj":"检验食物词汇和可数不可数、some/any的掌握","pr":"1) 听写本周25词（注意标出可数/不可数）。2) 设计一份英文菜单（前菜/主菜/饮品各3样+价格）。3) 和家人角色扮演点餐对话并录音。4) 复习第1-4周错词。","tip":"饮食是口语Part 1必考话题。今天的菜单和对话素材直接留作口语答案。"}},{"w":6,"p":1,"theme":"购物与金钱","d":[{"t":"商品与价格","obj":"学会谈论价格，掌握How much is...?","time":"40分钟","v":[{"w":"price","m":"价格","p":"n.","e":"The price is reasonable."},{"w":"cheap","m":"便宜的","p":"adj.","e":"This shirt is very cheap."},{"w":"expensive","m":"昂贵的","p":"adj.","e":"The camera is too expensive."},{"w":"buy","m":"买","p":"v.","e":"I want to buy a new phone."},{"w":"sell","m":"卖","p":"v.","e":"They sell fresh fruit here."}],"g":{"t":"How much is / are...? 问价格","exp":"单数问How much is it? 复数问How much are they? 回答：It's fifty yuan. / They're ten dollars each. 价格读法：$4.99读four ninety-nine。","ex":["How much is this bag? It's ninety-nine yuan.","How much are these apples?","The price includes tax."]},"pr":"1) 写5句问答（问5样东西的价格）。2) 用英语标出家里10样物品的估价。3) 口头描述：你最近买的最贵的东西。","tip":"听力价格题陷阱：$14和$40发音接近，区分方法是重音：fifTEEN重音在后，FIFty重音在前。"},{"t":"购物场所","obj":"学会说购物地点，掌握there be句型","time":"40分钟","v":[{"w":"shop","m":"商店","p":"n./v.","e":"I often shop online."},{"w":"market","m":"市场","p":"n.","e":"The morning market is very busy."},{"w":"mall","m":"购物中心","p":"n.","e":"The new mall has ten floors."},{"w":"store","m":"店铺","p":"n.","e":"The store opens at nine."},{"w":"online","m":"在线的","p":"adj./adv.","e":"I buy books online."}],"g":{"t":"there be 句型（某处有某物）","exp":"There is + 单数/不可数，There are + 复数：There is a mall near my home. There are many shops here. 就近原则：There is a pen and two books on the desk.","ex":["There is a big market near my home.","There are many stores in the mall.","Is there a bank around here?"]},"pr":"1) 用there be写6句描述自己家附近的购物场所。2) 改成疑问句自答。3) 画简易地图并标注英文。","tip":"there be和have的区别：there be表示存在（某处有），have表示拥有（某人有）。考试填空高频考is还是are。"},{"t":"挑选商品","obj":"学会挑选和试穿，掌握指示代词","time":"40分钟","v":[{"w":"size","m":"尺码；大小","p":"n.","e":"Do you have a bigger size?"},{"w":"color","m":"颜色","p":"n.","e":"I like this color very much."},{"w":"try on","m":"试穿","p":"phr.v.","e":"Can I try on these shoes?"},{"w":"fit","m":"合身；适合","p":"v.","e":"The dress fits you well."},{"w":"small","m":"小的","p":"adj.","e":"This one is too small for me."}],"g":{"t":"this / that / these / those 指示代词","exp":"this（这个，近处单数），that（那个，远处单数），these（这些，近处复数），those（那些，远处复数）。导购对话全靠它们：Do you have this in blue?","ex":["This shirt is too big.","How much are those shoes?","I like these colors."]},"pr":"1) 写一段买衣服的对话（8句，用上try on和size）。2) 指着家里物品说5句（this/that/these/those各至少1次）。3) 回答：What size do you wear?","tip":"试衣间门口那句Do you have a bigger one? 是购物场景万能句，雅思听力Section 1常出现。"},{"t":"付款方式","obj":"学会付款表达，掌握Can I have...请求句","time":"40分钟","v":[{"w":"money","m":"钱","p":"n.","e":"I don't have enough money with me."},{"w":"pay","m":"支付","p":"v.","e":"Can I pay by card?"},{"w":"cash","m":"现金","p":"n.","e":"I only have cash."},{"w":"card","m":"银行卡；卡片","p":"n.","e":"I will pay with my card."},{"w":"change","m":"零钱；找零","p":"n./v.","e":"Here is your change."}],"g":{"t":"Can I...? / I'll take it 付款场景句型","exp":"付款三连：Can I pay by card?（能刷卡吗）I'll take it.（我买了）Keep the change.（不用找了）。by card = with card = in cash，三个介词搭配都要认识。","ex":["Can I pay by credit card?","I'll take this one.","Do you take cash?"]},"pr":"1) 写一段结账对话（收银员+顾客8句）。2) 背熟付款三连句。3) 口头描述自己最近一次购物经历。","tip":"听力Section 1最后常考付款方式：cash / credit card / bank transfer，边听边写缩写再补全。"},{"t":"退换商品","obj":"学会退换货表达，初识一般过去时","time":"40分钟","v":[{"w":"return","m":"退回；返回","p":"v.","e":"I want to return this jacket."},{"w":"exchange","m":"交换；调换","p":"v./n.","e":"Can I exchange it for a bigger one?"},{"w":"receipt","m":"收据","p":"n.","e":"Do you still have the receipt?"},{"w":"refund","m":"退款","p":"n./v.","e":"I would like a full refund."},{"w":"broken","m":"坏掉的","p":"adj.","e":"The toy is broken."}],"g":{"t":"一般过去时初识（was / were）","exp":"过去的事用过去时：be动词变成was（I/he/she/it）和were（you/we/they）。I bought it yesterday（buy的过去式bought）。今天先记was/were和“动词过去式”这个概念。","ex":["I bought this phone last week.","The bag was broken when I opened it.","They were very expensive."]},"pr":"1) 写一段退换货对话（顾客+店员10句）。2) 用was/were写4句描述过去。3) 背诵：I'd like to return/exchange/refund...","tip":"退换货场景是听力Section 1高频场景，receipt、refund、exchange三个词必须一听就懂。"}],"sun":{"t":"第6周自检：购物话题","obj":"检验购物词汇和句型掌握情况","pr":"1) 听写本周25词。2) 写一段完整的购物经历（80词，用上过去时的was/were和过去式）。3) 角色扮演：退换货对话录音。4) 复习第1-5周错词。","tip":"购物是雅思听力Section 1的顶流场景，本周的对话句型会在考试中原样出现。"}},{"w":7,"p":1,"theme":"住房与社区","d":[{"t":"房间与房屋","obj":"学会说房屋房间，掌握there be复数","time":"40分钟","v":[{"w":"house","m":"房子","p":"n.","e":"They live in a big house."},{"w":"room","m":"房间","p":"n.","e":"My room is small but bright."},{"w":"bedroom","m":"卧室","p":"n.","e":"There are two bedrooms."},{"w":"kitchen","m":"厨房","p":"n.","e":"Mom is cooking in the kitchen."},{"w":"bathroom","m":"浴室","p":"n.","e":"The bathroom is next to my room."}],"g":{"t":"there be 的复数与否定","exp":"There are two bedrooms in the house. 否定：There aren't any parks nearby. 疑问：Is there a...? / Are there any...? 听力里数字+复数是填空高频考点。","ex":["There are three rooms in my apartment.","There isn't a garden.","Are there any shops near your home?"]},"pr":"1) 画出自己家的平面图，用英文标注每个房间。2) 用there be写6句描述自己家。3) 口头介绍：My home has...","tip":"描述住宿是口语Part 1高频题。平面图场景也是听力Section 1经典题型，方位词下周继续加强。"},{"t":"家具家电","obj":"学会说家具家电，掌握方位介词","time":"40分钟","v":[{"w":"bed","m":"床","p":"n.","e":"The bed is against the wall."},{"w":"table","m":"桌子","p":"n.","e":"Put the keys on the table."},{"w":"chair","m":"椅子","p":"n.","e":"This chair is very comfortable."},{"w":"fridge","m":"冰箱","p":"n.","e":"There is little food in the fridge."},{"w":"sofa","m":"沙发","p":"n.","e":"The cat is sleeping on the sofa."}],"g":{"t":"方位介词（in / on / under / behind / next to / between）","exp":"in the box（里面），on the table（上面），under the bed（下面），behind the door（后面），next to the sofa（旁边），between A and B（A和B之间）。描述位置全靠它们。","ex":["The keys are in the drawer.","The lamp is next to the bed.","The sofa is between the window and the door."]},"pr":"1) 用方位介词描述家里10样物品的位置。2) 玩“猜物品”游戏：描述位置让别人猜。3) 画卧室图，写5句描述。","tip":"听力地图题的核心就是方位介词+左右（on your left/right）。从描述自己的家开始练方向感。"},{"t":"社区设施","obj":"学会说社区场所，掌握near/next to等","time":"40分钟","v":[{"w":"park","m":"公园","p":"n.","e":"I take a walk in the park every evening."},{"w":"school","m":"学校","p":"n.","e":"My son's school is five minutes away."},{"w":"hospital","m":"医院","p":"n.","e":"The hospital is on Main Street."},{"w":"library","m":"图书馆","p":"n.","e":"I borrow books from the library."},{"w":"street","m":"街道","p":"n.","e":"Our street is quiet at night."}],"g":{"t":"near / next to / across from / around here","exp":"near=附近，next to=紧挨着，across from=对面，around here=这附近。问地方：Is there a bank near here? / Where is the nearest hospital?","ex":["The library is next to the bank.","The park is across from my school.","Is there a hospital around here?"]},"pr":"1) 画社区地图（含公园、学校、医院、图书馆、商店）。2) 写6句描述设施的位置。3) 口头介绍自己社区最方便的地方。","tip":"听力地图题第一步永远是“先在图中找到你现在的位置”，再跟着方位词走。培养方向感从描述社区开始。"},{"t":"城市与乡村","obj":"学会对比城乡，掌握was/were的过去描述","time":"40分钟","v":[{"w":"city","m":"城市","p":"n.","e":"Shanghai is a modern city."},{"w":"town","m":"城镇","p":"n.","e":"I grew up in a small town."},{"w":"village","m":"村庄","p":"n.","e":"My grandparents live in a village."},{"w":"quiet","m":"安静的","p":"adj.","e":"The village is quiet and peaceful."},{"w":"noisy","m":"吵闹的","p":"adj.","e":"The city center is too noisy."}],"g":{"t":"was / were 描述过去","exp":"十年前的小镇、小时候的村庄，都用was/were：My town was very quiet twenty years ago. 对比现在：Now it is noisy. 今昔对比是口语经典结构。","ex":["My village was small twenty years ago.","The streets were dirty before.","There were no tall buildings then."]},"pr":"1) 写5句今昔对比（家乡/小区的过去与现在）。2) 口头回答：Do you like the city or the countryside? Why? 3) 录音60秒描述自己的家乡。","tip":"今昔对比（used to / was）是雅思口语和写作的经典套路，现在打好was/were基础。"},{"t":"租房表达","obj":"学会租房场景词汇，掌握How many问答","time":"40分钟","v":[{"w":"rent","m":"租；租金","p":"v./n.","e":"We rent a flat near the school."},{"w":"move","m":"搬家；移动","p":"v.","e":"We will move to a new house."},{"w":"neighbor","m":"邻居","p":"n.","e":"My neighbor is very friendly."},{"w":"live","m":"居住","p":"v.","e":"How long have you lived here?"},{"w":"floor","m":"楼层；地板","p":"n.","e":"We live on the fifth floor."}],"g":{"t":"How many + 复数名词","exp":"问数量用How many+复数：How many rooms are there in your flat? 注意名词必须复数、be动词用are。楼层的介词用on：on the third floor。","ex":["How many bedrooms do you have?","We live on the sixth floor.","There are eight floors in our building."]},"pr":"1) 写5句自己家的基本情况（楼层、房间数、住了多久）。2) 写一段租房需求（3-4句）。3) 听力预演：默写房间类词汇。","tip":"租房是听力Section 1王牌场景：房间类型、租金、押金（deposit）、含不含bill，这些词听到就要反应。"}],"sun":{"t":"第7周自检：住房与社区","obj":"检验住房词汇、方位介词和过去式be动词","pr":"1) 听写本周25词。2) 画一张自己家+社区的完整地图，配10句英文描述。3) 写一段60词的My Hometown（今昔对比）。4) 复习第1-6周错词，整理“最难记的30词”卡片。","tip":"第7周是阶段一过半的节点。能流利介绍自己的家、社区和作息，就说明基础框架已经立起来了。"}},{"w":8,"p":1,"theme":"出行与交通","d":[{"t":"交通工具","obj":"学会说各种交通工具，掌握by+交通工具","time":"40分钟","v":[{"w":"bus","m":"公共汽车","p":"n.","e":"I take the bus to work."},{"w":"train","m":"火车","p":"n.","e":"The train leaves at eight."},{"w":"car","m":"小汽车","p":"n.","e":"My uncle drives a car."},{"w":"bike","m":"自行车","p":"n.","e":"I go to school by bike."},{"w":"plane","m":"飞机","p":"n.","e":"The plane takes off on time."}],"g":{"t":"by + 交通工具（出行方式）","exp":"乘坐某种交通工具用by：by bus / by train / by bike / by plane。步行例外：on foot。也常用take：take the bus / take a taxi。介词千万别写错。","ex":["I go to work by subway.","She goes to school on foot.","We took a taxi to the airport."]},"pr":"1) 写5句自己常用交通方式。2) 问家人：How do you go to work? 记录答案。3) 口头回答：坐飞机/火车/公交分别什么感觉？","tip":"交通方式是口语Part 1常规题，也是听力Section 1表格里的常驻列：bus/taxi/train/walk。"},{"t":"问路与指路","obj":"学会问路指路，掌握祈使句","time":"40分钟","v":[{"w":"turn","m":"转弯；转","p":"v./n.","e":"Turn left at the corner."},{"w":"left","m":"左边","p":"n./adj.","e":"The bank is on your left."},{"w":"right","m":"右边；正确的","p":"n./adj.","e":"Turn right at the traffic lights."},{"w":"straight","m":"直的；径直","p":"adj./adv.","e":"Go straight for two blocks."},{"w":"corner","m":"街角","p":"n.","e":"There is a cafe on the corner."}],"g":{"t":"祈使句（指路用语）","exp":"指路用祈使句，动词开头：Go straight. / Turn left. / Take the second right. / Cross the road. 否定：Don't turn here. 问路：Excuse me, how can I get to...? / Where is...?","ex":["Go straight and turn left.","Take the first turning on the right.","Don't cross the street here."]},"pr":"1) 写一段指路（从家到最近的超市，5句）。2) 口头给“游客”指路3次。3) 默写左右：on your left / on your right。","tip":"听力地图题就是问路指路的录音版。go along / turn at / cross，听到哪个词就在图上做对应动作。"},{"t":"车站与票务","obj":"掌握车站票务词汇，学会提建议","time":"40分钟","v":[{"w":"station","m":"车站","p":"n.","e":"The train station is very crowded."},{"w":"ticket","m":"票","p":"n.","e":"Two single tickets to London, please."},{"w":"platform","m":"站台","p":"n.","e":"The train leaves from Platform 3."},{"w":"airport","m":"机场","p":"n.","e":"We arrived at the airport early."},{"w":"passenger","m":"乘客","p":"n.","e":"The bus can carry forty passengers."}],"g":{"t":"情态动词 should（提建议）","exp":"提建议用should：You should take the early train. 否定：You shouldn't be late. 问建议：Should I buy a return ticket? 车站问询：Which platform...? / When does it leave?","ex":["You should take the 8:00 train.","Should I get off at the next stop?","You shouldn't carry so much luggage."]},"pr":"1) 写一段车站买票对话（8句）。2) 用should给要去机场的朋友提3条建议。3) 口头描述自己最近一次坐车/坐飞机的经历。","tip":"听力车站场景必考：platform number、departure time、single/return ticket，数字+名词组合要写快。"},{"t":"旅行计划","obj":"学会谈计划，掌握be going to将来时","time":"40分钟","v":[{"w":"travel","m":"旅行","p":"v./n.","e":"I love traveling by train."},{"w":"trip","m":"（短途）旅行","p":"n.","e":"We are planning a trip to Yunnan."},{"w":"plan","m":"计划","p":"v./n.","e":"I plan to visit my aunt."},{"w":"visit","m":"参观；拜访","p":"v.","e":"We visited the museum last year."},{"w":"beautiful","m":"美丽的","p":"adj.","e":"Hangzhou is a beautiful city."}],"g":{"t":"be going to（打算做某事）","exp":"表达计划好的将来：I am going to study abroad next year. 结构=am/is/are + going to + 动词原形。疑问：Are you going to travel this summer?","ex":["I am going to visit Beijing next month.","We are going to take the train.","She is going to learn swimming."]},"pr":"1) 写5句自己的旅行计划（be going to）。2) 问家人：What are you going to do this weekend? 3) 规划一次想去的旅行（口头2分钟）。","tip":"be going to和下周的will是“将来双雄”。计划用be going to，临时决定用will，下周对比学习。"},{"t":"旅行经历","obj":"学会讲过去的旅行，掌握一般过去时","time":"40分钟","v":[{"w":"flight","m":"航班；飞行","p":"n.","e":"Our flight was delayed two hours."},{"w":"hotel","m":"酒店","p":"n.","e":"The hotel room was clean and quiet."},{"w":"beach","m":"海滩","p":"n.","e":"We walked along the beach at sunset."},{"w":"tourist","m":"游客","p":"n.","e":"Many tourists visit this old town."},{"w":"enjoy","m":"享受；喜爱","p":"v.","e":"We enjoyed the local food very much."}],"g":{"t":"一般过去时（规则动词+ed）","exp":"过去发生的动作用动词过去式：visit→visited, enjoy→enjoyed, stay→stayed。否定借助did：I didn't enjoy it. 疑问：Did you enjoy the trip? 记住did出现，动词回原形。","ex":["We visited the Great Wall last summer.","I walked along the beach every morning.","She didn't like the hotel."]},"pr":"1) 写5句过去旅行做过的事（动词过去式）。2) 改成否定和疑问句各2句。3) 口头讲述一次难忘的旅行（60秒）。","tip":"讲故事全靠过去时。雅思口语Part 2的“描述一次经历”题，就是过去时大阅兵，不规则动词下周继续加强。"}],"sun":{"t":"第8周自检：出行与旅行","obj":"检验交通词汇和将来时、过去时的掌握","pr":"1) 听写本周25词。2) 写一段旅行计划（80词：去哪、怎么去、住哪、做什么）。3) 时态混合测试：翻译10句（现在/进行/将来/过去）。4) 复习第1-7周错词。","tip":"旅行是口语Part 1/2/3全都会出现的话题。今天的计划+经历两段文字都是以后的口语素材。"}},{"w":9,"p":1,"theme":"学校与学习","d":[{"t":"学科名称","obj":"学会说学科，掌握like+名词","time":"40分钟","v":[{"w":"math","m":"数学","p":"n.","e":"Math is my favorite subject."},{"w":"history","m":"历史","p":"n.","e":"We learned a lot of history."},{"w":"science","m":"科学","p":"n.","e":"Science classes are interesting."},{"w":"art","m":"美术；艺术","p":"n.","e":"She is good at art."},{"w":"music","m":"音乐","p":"n.","e":"I listen to music when I study."}],"g":{"t":"like / be good at / be interested in","exp":"表达喜好三件套：I like math. / I am good at science.（擅长）/ I am interested in history.（对...感兴趣）注意good at和interested in的介词，后面接动词时用ing。","ex":["I am interested in history.","She is good at music.","We don't like exams."]},"pr":"1) 写自己喜欢和不喜欢的学科（各3句+原因）。2) 问家人最擅长的科目。3) 口头描述自己学生时代的学科情况。","tip":"谈学科爱好的句子结构以后全部能迁移到任何话题（食物、运动、工作），这是万能句型。"},{"t":"校园场所","obj":"学会说校园场所，综合运用there be","time":"40分钟","v":[{"w":"classroom","m":"教室","p":"n.","e":"Our classroom is on the second floor."},{"w":"playground","m":"操场","p":"n.","e":"The students are on the playground."},{"w":"office","m":"办公室","p":"n.","e":"The teachers' office is next to the library."},{"w":"hall","m":"礼堂；大厅","p":"n.","e":"The concert is in the school hall."},{"w":"lab","m":"实验室","p":"n.","e":"We have science classes in the lab."}],"g":{"t":"校园场景描述（there be综合）","exp":"描述学校布局：There is a library behind the teaching building. There are two playgrounds near the gate. 数量+地点+方位介词，一口气全用上。","ex":["There is a big hall in our school.","There are four computer labs.","The playground is behind the classrooms."]},"pr":"1) 画出自己（或孩子）学校的平面图。2) 用there be+方位介词写8句描述。3) 口头带“新生”逛校园（60秒）。","tip":"学校场景=听力地图题的兄弟。练熟自己学校的描述，任何校园图都能套。"},{"t":"学习用品","obj":"学会说文具，掌握whose疑问句","time":"40分钟","v":[{"w":"pen","m":"钢笔；笔","p":"n.","e":"May I borrow your pen?"},{"w":"notebook","m":"笔记本","p":"n.","e":"I write new words in my notebook."},{"w":"bag","m":"书包；包","p":"n.","e":"My bag is heavy with books."},{"w":"ruler","m":"尺子","p":"n.","e":"Draw a line with the ruler."},{"w":"textbook","m":"教科书","p":"n.","e":"Open your textbooks to page 20."}],"g":{"t":"Whose...? 与名词性物主代词","exp":"问归属：Whose pen is this? 回答：It's mine / yours / his / hers / ours / theirs（名词性物主代词单独用，后面不加名词）。对比形容词性：my pen vs mine。","ex":["Whose notebook is this? It's mine.","Is this bag hers?","Those textbooks are theirs."]},"pr":"1) 指着家里物品问5句Whose...?并回答。2) 写5句（my.../mine各至少2次）。3) 整理自己的英文学习用品清单。","tip":"mine/yours这类词是听力填空送分点，拼错hers/theirs很可惜，今天一次记牢。"},{"t":"课堂活动","obj":"学会课堂用语，掌握can表能力","time":"40分钟","v":[{"w":"listen","m":"听","p":"v.","e":"Listen to the recording twice."},{"w":"spell","m":"拼写","p":"v.","e":"Can you spell your name?"},{"w":"answer","m":"回答；答案","p":"v./n.","e":"Answer the question in English."},{"w":"ask","m":"问","p":"v.","e":"Ask the teacher if you don't understand."},{"w":"repeat","m":"重复","p":"v.","e":"Repeat after me, please."}],"g":{"t":"can / can't（能力）","exp":"表达能力：I can swim. / She can't drive. 疑问：Can you speak English? 肯定回答：Yes, I can. 课堂用语全是祈使句：Listen! / Repeat! / Look at...!","ex":["I can understand slow English.","Can you spell this word?","She can't answer this question."]},"pr":"1) 写5句自己会做/不会做的事（can/can't）。2) 写5句课堂指令并表演出来。3) 口头回答：What can you do well?","tip":"can是口语里最万能的词之一。以后学英语过程每天问自己：Can I say this in English? 保持饥饿感。"},{"t":"考试与成绩","obj":"学会谈论考试，掌握because因果","time":"40分钟","v":[{"w":"exam","m":"考试","p":"n.","e":"The final exam is next week."},{"w":"test","m":"测验","p":"n./v.","e":"We have a spelling test today."},{"w":"pass","m":"通过","p":"v.","e":"I passed the driving test."},{"w":"fail","m":"不及格；失败","p":"v.","e":"He failed the math exam again."},{"w":"grade","m":"成绩；年级","p":"n.","e":"She got a good grade in English."}],"g":{"t":"because / so（因果表达）","exp":"because接原因：I was late because the bus broke down. so接结果：The bus broke down, so I was late. 口语回答Why问题必须带because，写作文因果连接靠because/so。","ex":["I passed because I studied hard.","The test was hard, so I failed.","Why are you happy? Because I got an A!"]},"pr":"1) 写5句关于考试/成绩的因果句（because和so各半）。2) 口头回答：Do exams make you nervous? Why? 3) 给自己最近的英语学习打个分并说明原因。","tip":"答口语题不带because就像吃饭不嚼——考官立刻觉得你不会扩展。从今天起每个回答都带原因。"}],"sun":{"t":"第9周自检：学校与学习","obj":"检验学科、校园词汇和can/because的掌握","pr":"1) 听写本周25词。2) 写80词短文《My School Days》（用过去时描述、现在时总结）。3) 自由问答自测10题（模拟口语Part 1）。4) 复习第1-8周错词。","tip":"第9周了，检查一下：这周随机抽10个旧词，能想起意思吗？记不住的词做张卡片贴墙上。"}},{"w":10,"p":1,"theme":"工作与职业","d":[{"t":"职业名称","obj":"学会更多职业，掌握What do you do?","time":"40分钟","v":[{"w":"engineer","m":"工程师","p":"n.","e":"My cousin is a software engineer."},{"w":"manager","m":"经理","p":"n.","e":"The manager is in a meeting."},{"w":"secretary","m":"秘书","p":"n.","e":"The secretary answers the phone."},{"w":"lawyer","m":"律师","p":"n.","e":"The lawyer works long hours."},{"w":"accountant","m":"会计","p":"n.","e":"She is an accountant in a bank."}],"g":{"t":"What do you do?（问职业）","exp":"问职业固定句：What do you do? / What does your father do? 回答：I am a/an + 职业，或I work in/for + 地点/公司。别按中文思维说My job is...（太生硬）。","ex":["What do you do? I am a nurse.","What does your mother do? She is a manager.","I work for a tech company."]},"pr":"1) 写自己和3位家人的职业介绍。2) 自问自答What do you do? 5组。3) 口头描述自己理想的工作是什么、为什么。","tip":"职业是口语Part 1开胃题。I work in.../I work for...两个介词：in+行业，for+公司。"},{"t":"工作场所","obj":"学会说工作地点，掌握work in/at","time":"40分钟","v":[{"w":"company","m":"公司","p":"n.","e":"He joined the company last year."},{"w":"factory","m":"工厂","p":"n.","e":"The factory makes shoes."},{"w":"bank","m":"银行","p":"n.","e":"I go to the bank on Fridays."},{"w":"workshop","m":"车间；工坊","p":"n.","e":"The workshop is noisy but bright."},{"w":"team","m":"团队","p":"n.","e":"Our team has eight people."}],"g":{"t":"work in / work for / work as","exp":"work in a hospital（在...场所），work for Huawei（为...公司），work as a teacher（担任...职位）。三个介词三个含义，面试口语全靠它们介绍自己。","ex":["I work in a small office.","My brother works for a bank.","She works as a manager."]},"pr":"1) 用work in/for/as各写2句（自己+家人）。2) 口头介绍自己的工作（或理想工作）。3) 写出5个行业的英文（科技/教育/医疗/金融/制造）。","tip":"介绍工作三连：I work for X. / I work in the X department. / I work as a/an X. 面试口语直接套。"},{"t":"工作日常","obj":"学会描述工作日常，综合运用频度副词","time":"40分钟","v":[{"w":"meeting","m":"会议","p":"n.","e":"We have a meeting every Monday."},{"w":"email","m":"电子邮件","p":"n./v.","e":"I send emails to clients every day."},{"w":"report","m":"报告","p":"n./v.","e":"I am writing the sales report."},{"w":"busy","m":"忙碌的","p":"adj.","e":"This week is very busy."},{"w":"overtime","m":"加班（时间）","p":"n./adv.","e":"She often works overtime."}],"g":{"t":"描述日常工作的句型组合","exp":"时间+频度+动作：I usually start work at nine. / We have meetings twice a week. / I check emails first thing in the morning. 动词短语积累：have a meeting, send an email, write a report, take a break。","ex":["I check my emails before nine.","We have a team meeting every morning.","He works overtime three times a week."]},"pr":"1) 写6句自己（或家人）的工作日常。2) 画时间轴标注一天工作安排。3) 口头描述：你最忙的一天是什么样的。","tip":"工作日常=口语Part 1的Do you work or are you a student?后续展开题。提前备好一段40秒的日常描述。"},{"t":"求职面试","obj":"学会求职词汇，掌握would like","time":"40分钟","v":[{"w":"interview","m":"面试；采访","p":"n./v.","e":"I have a job interview tomorrow."},{"w":"resume","m":"简历","p":"n.","e":"Send your resume before Friday."},{"w":"skill","m":"技能","p":"n.","e":"Communication is an important skill."},{"w":"experience","m":"经验；经历","p":"n.","e":"I have three years of experience."},{"w":"hire","m":"雇用","p":"v.","e":"The company hired ten new workers."}],"g":{"t":"would like（想要；愿意）","exp":"would like比want礼貌：I would like to apply for this job. 缩写I'd like。问对方：Would you like to join our team? 口语面试全程用would显得专业。","ex":["I would like to work in your company.","I'd like to apply for the manager position.","Would you like to leave a message?"]},"pr":"1) 写5句面试自我介绍（I'd like to.../I have...experience）。2) 和家人模拟一段简短面试问答。3) 写出自己最重要的3项技能。","tip":"雅思口语本质上就是一场面试：提前把I'd like to...背熟，语气立刻从容。"},{"t":"职业理想","obj":"学会谈未来职业，掌握will将来时","time":"40分钟","v":[{"w":"dream","m":"梦想","p":"n./v.","e":"My dream is to be a pilot."},{"w":"future","m":"未来","p":"n./adj.","e":"What do you want to do in the future?"},{"w":"become","m":"变成；成为","p":"v.","e":"She wants to become a doctor."},{"w":"hope","m":"希望","p":"v./n.","e":"I hope to get a better job."},{"w":"succeed","m":"成功","p":"v.","e":"Work hard and you will succeed."}],"g":{"t":"will（一般将来时）","exp":"will+动词原形表将来：I will be a good engineer. 否定won't。与be going to的区别：be going to是计划好的，will是临时决定或预测：I will help you（临时）。两者都可以表预测。","ex":["I will work harder next year.","She will be a great teacher.","I think robots will do more jobs."]},"pr":"1) 写5句自己的职业规划（will和be going to各半）。2) 口头回答：Where do you see yourself in five years? 3) 描述10年后的自己（工作、生活、城市）。","tip":"谈未来用will+I believe/I hope，立刻有高级感：I believe I will pass the IELTS test with 6.5."}],"sun":{"t":"第10周自检：工作话题","obj":"检验职业词汇和will/would like的掌握","pr":"1) 听写本周25词。2) 写80词短文《My Dream Job》（现在情况+未来规划）。3) 模拟面试自测：回答5个面试常见问题并录音。4) 复习第1-9周错词。","tip":"工作话题是雅思口语三大场景之一（工作、学习、住所），本周的内容直接是考试素材。"}},{"w":11,"p":1,"theme":"兴趣爱好","d":[{"t":"运动爱好","obj":"学会说运动项目，掌握play/go/do搭配","time":"40分钟","v":[{"w":"sport","m":"运动","p":"n.","e":"What sports do you like?"},{"w":"football","m":"足球","p":"n.","e":"We play football after class."},{"w":"basketball","m":"篮球","p":"n.","e":"He is good at basketball."},{"w":"swim","m":"游泳","p":"v./n.","e":"I swim twice a week in summer."},{"w":"run","m":"跑步；奔跑","p":"v.","e":"She runs in the park every morning."}],"g":{"t":"play / go / do 与运动搭配","exp":"球类用play：play football。到达场地才能做的运动用go+ing：go swimming / go running / go fishing。健身操瑜伽等用do：do yoga / do exercise。搭配错了母语者立刻听出来。","ex":["I play basketball on Saturdays.","We go swimming in summer.","She does yoga every evening."]},"pr":"1) 写自己常做的5项运动（注意搭配）。2) 问家人：What sports do you do? 3) 口头描述自己一周的运动安排。","tip":"go+doing结构是考点：go shopping / go fishing / go jogging。听力里出现频率极高。"},{"t":"文艺爱好","obj":"学会说文艺活动，综合运用enjoy doing","time":"40分钟","v":[{"w":"music","m":"音乐","p":"n.","e":"I listen to music on my way home."},{"w":"movie","m":"电影","p":"n.","e":"We watched an old movie last night."},{"w":"dance","m":"跳舞；舞蹈","p":"v./n.","e":"She dances very well."},{"w":"sing","m":"唱歌","p":"v.","e":"He sings in the shower every day."},{"w":"paint","m":"绘画","p":"v.","e":"My aunt paints in her free time."}],"g":{"t":"be interested in + 名词/doing","exp":"对某事感兴趣：I am interested in music / in learning guitar. 也可以说My hobby is painting. 或I am crazy about movies（超爱电影）。三个句型轮着用。","ex":["I am interested in classical music.","My hobby is painting.","I am crazy about science fiction movies."]},"pr":"1) 写5句自己的文艺爱好（三个句型轮用）。2) 描述自己最近看的一部电影/听的一首歌。3) 口头回答：Do you prefer watching movies at home or in the cinema?","tip":"谈爱好别只说I like。轮换enjoy / be interested in / be crazy about，词汇多样性立刻+1分。"},{"t":"阅读与游戏","obj":"学会谈阅读游戏，掌握spend time","time":"40分钟","v":[{"w":"novel","m":"小说","p":"n.","e":"I finished the novel in two days."},{"w":"magazine","m":"杂志","p":"n.","e":"She reads fashion magazines."},{"w":"game","m":"游戏；比赛","p":"n.","e":"We play card games on weekends."},{"w":"chess","m":"国际象棋","p":"n.","e":"My grandpa plays chess in the park."},{"w":"story","m":"故事","p":"n.","e":"Grandma told me many stories."}],"g":{"t":"spend time / money on sth (in doing sth)","exp":"花费时间或钱：I spend two hours a day on reading. / She spends a lot of money on books. 口语高频替换：It takes me two hours to read.（It takes句型）。","ex":["I spend an hour a day on English.","He spends too much time on games.","It takes me 30 minutes to read."]},"pr":"1) 用spend...on写5句（时间+金钱各半）。2) 用It takes...改写其中3句。3) 口头回答：How much time do you spend on your phone every day?","tip":"spend和take句型可以互相改写，口语里灵活切换能明显提升流利度。"},{"t":"户外活动","obj":"学会说户外活动，掌握How long问答","time":"40分钟","v":[{"w":"hike","m":"远足；徒步","p":"v./n.","e":"We hiked in the mountains."},{"w":"camp","m":"露营","p":"v./n.","e":"We camped by the lake."},{"w":"fish","m":"钓鱼","p":"v.","e":"They go fishing on Sundays."},{"w":"picnic","m":"野餐","p":"n.","e":"We had a picnic in the park."},{"w":"climb","m":"爬；攀登","p":"v.","e":"The kids climbed the hill quickly."}],"g":{"t":"How long...?（问时长）","exp":"问时长：How long did the hike take? 回答：It took three hours. / For two days. 问频率用How often，问时长用How long，别混。现在完成时预告：How long have you lived here?（下周细讲）。","ex":["How long does the movie last? Two hours.","How long did you stay? For a week.","It took us all day to climb."]},"pr":"1) 写自己一次户外活动的经历（5句，含How long自问自答）。2) 计划一次周末户外活动并写英文安排。3) 口头描述：最喜欢的一次野餐/远足。","tip":"户外活动是口语Part 2“描述一次经历”的优质素材：时间+地点+人物+做了什么+感受，五要素齐活。"},{"t":"偏好表达","obj":"学会表达偏好程度，掌握比较级初步","time":"40分钟","v":[{"w":"love","m":"爱；热爱","p":"v.","e":"I love outdoor activities."},{"w":"prefer","m":"更喜欢","p":"v.","e":"I prefer tea to coffee."},{"w":"favorite","m":"最喜欢的","p":"adj./n.","e":"Blue is my favorite color."},{"w":"keen","m":"热衷的（keen on）","p":"adj.","e":"He is keen on photography."},{"w":"popular","m":"受欢迎的；流行的","p":"adj.","e":"Basketball is popular in our school."}],"g":{"t":"比较级初步（than比较）","exp":"形容词比较级加-er+than：Reading is cheaper than watching movies. 长形容词用more：more interesting than。prefer A to B结构固定（不用than）：I prefer tea to coffee.","ex":["I prefer swimming to running.","Hiking is more interesting than shopping.","This game is easier than chess."]},"pr":"1) 写5句偏好对比句（prefer...to...和-er than各半）。2) 口头回答：Do you prefer indoor or outdoor activities? Why? 3) 总结自己前11周最喜欢的3个学习模块并比较。","tip":"prefer A to B是固定搭配，考试写prefer...than直接算错。今天一次记牢。"}],"sun":{"t":"第11周自检：兴趣爱好","obj":"检验爱好词汇和偏好表达的掌握","pr":"1) 听写本周25词。2) 写100词短文《My Hobbies and Free Time》（爱好+频率+偏好+原因）。3) 口语模拟：回答Do you like...? / What do you do in your free time? 并录音。4) 复习第1-10周错词。","tip":"爱好话题人人必考。今天的短文就是你的口语模板，背熟后考试直接流利输出。"}},{"w":12,"p":1,"theme":"天气与季节","d":[{"t":"天气现象","obj":"学会描述天气，掌握What's the weather like?","time":"40分钟","v":[{"w":"sunny","m":"晴朗的","p":"adj.","e":"It is sunny and warm today."},{"w":"rainy","m":"下雨的","p":"adj.","e":"It is a rainy day in London."},{"w":"windy","m":"有风的","p":"adj.","e":"It is windy near the sea."},{"w":"cloudy","m":"多云的","p":"adj.","e":"The sky is cloudy this morning."},{"w":"snowy","m":"下雪的","p":"adj.","e":"The city is beautiful when it is snowy."}],"g":{"t":"What's the weather like?（问天气）","exp":"问天气固定句：What's the weather like today? 或How is the weather? 回答：It is + 形容词（It's sunny.）。注意“下雨”口语也可说It's raining（进行时表当下）。","ex":["What's the weather like today? It's windy.","It's cloudy and cold outside.","It is raining again."]},"pr":"1) 连续记录本周7天天气（英文）。2) 自问自答天气5组。3) 口头描述自己家乡四季的天气特点。","tip":"天气是英语的“聊天开场白”，就像中文的“吃了吗”。口语Part 1的Weather题几乎必考。"},{"t":"温度与体感","obj":"学会谈温度，掌握It is + adj句型","time":"40分钟","v":[{"w":"hot","m":"热的；辣的","p":"adj.","e":"The soup is very hot."},{"w":"cold","m":"冷的","p":"adj.","e":"Winter here is very cold."},{"w":"warm","m":"温暖的","p":"adj.","e":"Spring is warm and pleasant."},{"w":"cool","m":"凉爽的","p":"adj.","e":"Autumn is cool in the morning."},{"w":"temperature","m":"温度","p":"n.","e":"The temperature is 35 degrees today."}],"g":{"t":"It is + 形容词（描述自然现象）","exp":"英语说“天气热”必须用it作主语：It is hot.（不是The weather is hot也行，但It is更常用）。温度读法：35°C读thirty-five degrees。零下：minus five degrees。","ex":["It is too hot to sleep.","It was warm yesterday.","The temperature drops below zero in winter."]},"pr":"1) 写6句本周天气+温度描述。2) 说出家乡最热/最冷月份数字。3) 口头对比夏天和冬天的感受。","tip":"It句型是英语的“隐形主语”：It's raining. It's cold. It's 8 o'clock. 全部用它，中文思维直译就会错。"},{"t":"四季变化","obj":"学会谈四季，写出流畅的描述","time":"40分钟","v":[{"w":"spring","m":"春天","p":"n.","e":"Flowers come out in spring."},{"w":"summer","m":"夏天","p":"n.","e":"We swim a lot in summer."},{"w":"autumn","m":"秋天","p":"n.","e":"Leaves turn yellow in autumn."},{"w":"winter","m":"冬天","p":"n.","e":"It often snows in winter."},{"w":"season","m":"季节","p":"n.","e":"Which season do you like best?"}],"g":{"t":"in + 季节 & My favorite season is...","exp":"季节前的介词用in：in spring / in winter。描述最爱季节的套路：My favorite season is autumn because it is cool and I can go hiking. 万能公式：季节+天气+活动+感受。","ex":["My favorite season is spring because everything turns green.","In winter we make snowmen.","Autumn is the best season for hiking."]},"pr":"1) 写自己最爱的季节（公式：季节+天气+活动+感受，60词）。2) 对比两个季节写3句。3) 口头描述四季各一句。","tip":"“最爱季节”是口语经典题。背熟今天写的段落，考试被问到直接输出。"},{"t":"自然景观","obj":"学会说自然景观，综合运用there be","time":"40分钟","v":[{"w":"mountain","m":"山","p":"n.","e":"There are many mountains in the west."},{"w":"river","m":"河","p":"n.","e":"The river runs through the town."},{"w":"sea","m":"海","p":"n.","e":"We spent the summer by the sea."},{"w":"forest","m":"森林","p":"n.","e":"The forest is quiet in the early morning."},{"w":"beach","m":"海滩","p":"n.","e":"The beach gets crowded on weekends."}],"g":{"t":"家乡自然描述（there be + 方位 + 季节）","exp":"描述家乡地理：My hometown is in the south, near a big river. There are green mountains around it. 组合拳：方位+地形+季节+活动。","ex":["There is a long river near my village.","There are mountains around the city.","The beach is beautiful in summer."]},"pr":"1) 写5句家乡的自然景观描述。2) 口头描述一个去过的自然景点（60秒）。3) 把描述+天气组合成一段话。","tip":"口语Part 2“Describe a place you like”最常用素材就是家乡和景点，今天的句子直接入库。"},{"t":"天气与生活","obj":"学会谈天气影响，掌握感叹句","time":"40分钟","v":[{"w":"umbrella","m":"雨伞","p":"n.","e":"Take your umbrella, it may rain."},{"w":"coat","m":"外套","p":"n.","e":"You need a warm coat in winter."},{"w":"forecast","m":"天气预报","p":"n./v.","e":"The forecast says it will snow."},{"w":"degree","m":"度；程度","p":"n.","e":"Water freezes at zero degrees."},{"w":"change","m":"变化","p":"v./n.","e":"The weather changes quickly here."}],"g":{"t":"感叹句（What a...! / How...!）","exp":"What + a + 形容词 + 名词：What a sunny day! What a heavy rain! How + 形容词：How cold it is! 感叹句让口语立刻生动，聊天标配。","ex":["What a beautiful day!","What terrible weather!","How windy it is today!"]},"pr":"1) 写6个感叹句（What/How各3个）。2) 写一段“天气影响心情/计划”的话（4句）。3) 口头播报明天天气+穿衣建议。","tip":"聊天想自然就带感叹句：What a lovely day! 老外天天说，你也要会说。"}],"sun":{"t":"第12周自检：天气与自然","obj":"检验天气词汇和描述句型的掌握","pr":"1) 听写本周25词。2) 写80词短文《My Favorite Season》。3) 录制60秒英文天气播报（今天+明天+周末建议）。4) 复习第1-11周错词。","tip":"天气播报是经典口语练习法：语速、重音、流利度一次全练到，还很好玩。"}},{"w":13,"p":1,"theme":"情感健康与阶段总结","d":[{"t":"基本情绪","obj":"学会说情绪，掌握be+情感形容词","time":"40分钟","v":[{"w":"happy","m":"快乐的","p":"adj.","e":"I am happy to see you again."},{"w":"sad","m":"悲伤的","p":"adj.","e":"The movie made me sad."},{"w":"excited","m":"兴奋的","p":"adj.","e":"The kids are excited about the trip."},{"w":"tired","m":"疲倦的","p":"adj.","e":"I am too tired to cook tonight."},{"w":"bored","m":"无聊的","p":"adj.","e":"He got bored at the meeting."}],"g":{"t":"be + 情感形容词 & excited / exciting","exp":"情绪表达：I am bored（人感到）/ The movie is exciting（事物令人...）。人-ed、物-ing是分水岭：bored vs boring, interested vs interesting。","ex":["I am interested in this story.","The trip was exciting.","This lesson is boring."]},"pr":"1) 写6句自己这周的情绪（不同形容词）。2) 用-ed/-ing形容词各造3句（人/物）。3) 口头回答：How do you feel about learning English?","tip":"I'm boring（我好无聊/惹人烦）和I'm bored（我感到无聊）意思完全不同，考试写错会闹笑话。"},{"t":"复杂情绪","obj":"学会更多情绪词，掌握make+宾语+形容词","time":"40分钟","v":[{"w":"angry","m":"生气的","p":"adj.","e":"Don't be angry with me."},{"w":"afraid","m":"害怕的","p":"adj.","e":"She is afraid of dogs."},{"w":"surprised","m":"惊讶的","p":"adj.","e":"I was surprised at the news."},{"w":"worried","m":"担心的","p":"adj.","e":"Mom is worried about my health."},{"w":"glad","m":"高兴的","p":"adj.","e":"I am glad you came."}],"g":{"t":"make + 人 + 形容词（让某人怎样）","exp":"The music makes me happy.（这音乐让我开心。）否定：Don't make her sad. 情绪表达升级：be afraid of / be worried about两个介词搭配要记牢。","ex":["Rainy days make me sleepy.","The good news made us excited.","Don't make the children wait."]},"pr":"1) 用make+人+形容词写5句（什么让你开心/难过）。2) 用afraid of/worried about各造2句。3) 口头描述一次让你surprised的经历。","tip":"make sb happy这类使役结构在写作里非常好用：Music makes study less stressful."},{"t":"身体不适","obj":"学会说病痛，掌握have got表达不适","time":"40分钟","v":[{"w":"sick","m":"生病的；恶心的","p":"adj.","e":"She feels sick this morning."},{"w":"hurt","m":"疼痛；伤害","p":"v.","e":"My back hurts after work."},{"w":"headache","m":"头痛","p":"n.","e":"I have a bad headache."},{"w":"toothache","m":"牙痛","p":"n.","e":"The toothache kept me awake."},{"w":"medicine","m":"药","p":"n.","e":"Take this medicine twice a day."}],"g":{"t":"have got / have + 病痛（描述不适）","exp":"说病痛直接have got：I have got a headache / a cold / a fever. 程度：a slight headache（轻）/ a terrible backache（重）。注意ache类名词可数：a headache。","ex":["I have got a sore throat.","She has a bad cold.","My legs hurt after the hike."]},"pr":"1) 写5句描述常见不适（自己或家人的经历）。2) 写一段“向老师请假”的英文便条（病痛+请求）。3) 口头自述：感冒时你会怎么做。","tip":"看病场景是听力Section 1-2常客：symptom听不懂就全盘皆输，头疼脑热的词今天全记牢。"},{"t":"关心与建议","obj":"学会表达关心，掌握Why...? Because...问答","time":"40分钟","v":[{"w":"feel","m":"感觉","p":"v.","e":"How are you feeling today?"},{"w":"better","m":"更好的（well比较级）","p":"adj.","e":"I feel much better now."},{"w":"rest","m":"休息","p":"v./n.","e":"You need a good rest."},{"w":"take care","m":"保重；小心","p":"phr.","e":"Take care of yourself."},{"w":"help","m":"帮助","p":"v./n.","e":"Can I help you with anything?"}],"g":{"t":"关心他人的句型组合","exp":"问候：How are you feeling? 建议：You should rest. / You'd better see a doctor.（had better+原形）安慰：Don't worry, you will get better soon. 关心+建议+安慰三连。","ex":["You should drink more water.","You'd better stay in bed today.","Don't worry, it is nothing serious."]},"pr":"1) 写一段关心生病朋友的对话（8句）。2) 用should/had better给自己写3条健康建议。3) 口头回答：What do you do when you feel stressed?","tip":"You'd better+动词原形，考口语时用这句立刻显得地道。注意语气委婉，别对长辈滥用。"},{"t":"第一阶段总结","obj":"盘点13周学习成果，制定下阶段目标","time":"45分钟","v":[{"w":"review","m":"复习","p":"v./n.","e":"Review is the best teacher."},{"w":"remember","m":"记住；记得","p":"v.","e":"I can remember most of the words now."},{"w":"practice","m":"练习；实践","p":"v./n.","e":"Practice makes perfect."},{"w":"progress","m":"进步","p":"n./v.","e":"You have made great progress."},{"w":"confidence","m":"信心","p":"n.","e":"I have more confidence in English now."}],"g":{"t":"阶段一语法总串讲","exp":"13周语法全景：be动词（am/is/are）→人称物主代词→一般现在时→现在进行时→一般过去时→be going to/will→情态动词（can/should/could/would like）→there be。核心主线：能用英语描述自己、家人、日常、过去和未来。","ex":["I am a student and I study English every day.","Yesterday I reviewed all my notes.","Next year I will take the IELTS test."]},"pr":"1) 自测：从13周词汇中随机抽30个，默写意思。2) 写100词短文《My English Learning in 13 Weeks》（用上至少4种时态）。3) 给阶段二（14-26周）写3个目标。","tip":"13周前你可能是零基础，现在已能进行基础自我表达。慢就是快：基础打牢，后面加速才不翻车。"}],"sun":{"t":"阶段一毕业考：基础起步总测试","obj":"全面检验第1-13周（91天）学习成果","pr":"1) 词汇大考：从13周325词中随机抽50个，盖中文默写英文意思（≥40为合格）。2) 语法50题自测：时态选择+句型转换。3) 口语大考：录音回答10个问题（自我介绍/家庭/日常/爱好/天气各2题）。4) 估分：正确率+流利度自评，写入学习笔记。","tip":"达标了？恭喜进入阶段二！没达标也正常——回去把错题对应的天数重学一遍，磨刀不误砍柴工。"}}];
